-- ==========================================================
-- CamTix Event Service Database Schema & Seed Data
-- Database: camtix_event_db
-- ==========================================================

SET statement_timeout = 0;
SET lock_timeout = 0;
SET client_encoding = 'UTF8';
SET standard_conforming_strings = on;
SET check_function_bodies = false;
SET client_min_messages = warning;
SET row_security = off;

-- Drop existing tables if they exist
DROP TABLE IF EXISTS public.tickets CASCADE;
DROP TABLE IF EXISTS public.events CASCADE;

-- ----------------------------------------------------------
-- Table: events
-- ----------------------------------------------------------
CREATE TABLE public.events (
    id_event BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    event_name VARCHAR(255) NOT NULL,
    artist_name VARCHAR(255),
    city VARCHAR(255),
    location VARCHAR(255),
    event_date DATE,
    event_time VARCHAR(255),
    category VARCHAR(255),
    description TEXT,
    picture TEXT,
    status VARCHAR(255),
    slug VARCHAR(255) UNIQUE,
    created_at TIMESTAMP(6) WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    deleted_at TIMESTAMP(6) WITHOUT TIME ZONE
);

ALTER TABLE public.events OWNER TO postgres;

-- ----------------------------------------------------------
-- Table: tickets
-- ----------------------------------------------------------
CREATE TABLE public.tickets (
    id_ticket BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    ticket_type VARCHAR(255),
    price NUMERIC(38,2),
    stock INTEGER,
    description VARCHAR(255),
    event_id BIGINT REFERENCES public.events(id_event) ON DELETE CASCADE,
    created_at TIMESTAMP(6) WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP(6) WITHOUT TIME ZONE DEFAULT CURRENT_TIMESTAMP
);

ALTER TABLE public.tickets OWNER TO postgres;

