-- ----------------------------------------------------------
-- Sequence Alignment
-- ----------------------------------------------------------
SELECT pg_catalog.setval('public.events_id_event_seq', (SELECT MAX(id_event) FROM public.events), true);
SELECT pg_catalog.setval('public.tickets_id_ticket_seq', (SELECT MAX(id_ticket) FROM public.tickets), true);
